document.querySelectorAll('.btn,.quick-card,.event-card,.announcement-card').forEach(el=>{el.addEventListener('pointerdown',()=>el.classList.add('tap-active'));el.addEventListener('pointerup',()=>setTimeout(()=>el.classList.remove('tap-active'),140));el.addEventListener('pointerleave',()=>el.classList.remove('tap-active'));});
